/// <summary>
/// Live aggregation over the Stock stream, keyed by productId. Nothing registers a projection for this:
/// Marten folds it on demand when the decider asks.
///
/// ONE Apply, FOR ONE EVENT TYPE, AND THAT IS THE POINT. Our stream holds only what we DECIDED. There is no
/// <c>Apply(StockNoticed)</c> here because <see cref="StockNoticed"/> is never appended to our store — it is
/// the warehouse's event, it lives in the warehouse's band on the model, and the whole reason the translation
/// exists is to keep their vocabulary out of our history.
///
/// The generator scaffolded exactly this, with only <c>Apply(StockLevelSet)</c>. **The first version of this
/// folder called that a generator bug and hand-added a fold for the foreign event.** That was the error, not
/// the scaffold: filtering the fold to events the system OWNS is precisely right, and the doc comment about
/// folding "every event of the stream" means every event of the stream — which the foreign one is not.
///
/// A PURE FOLD WITH NO RULES IN IT. Every refusal lives in <see cref="ApplyStockNoticeHandler"/>.
/// </summary>
public sealed record TranslateStockNoticeState
{
    public Guid Id { get; init; }

    /// <summary>Marten's convention, used for optimistic concurrency.</summary>
    public int Version { get; set; }

    /// <summary>
    /// The stream key IS the identity field — one Guid, no composition. So the whole store is
    /// <c>StreamIdentity.AsGuid</c>, which is what the generator derived from the swimlane's identity=.
    /// </summary>
    public static Guid StreamKey(Guid productId) => productId;

    /// <summary>
    /// Notices we have already translated, by the warehouse's own notice id.
    ///
    /// A FOREIGN ID ON OUR EVENT IS NOT THE SAME THING AS THEIR SCHEMA. This is one correlation value, carried
    /// so that a redelivery is recognisable and so a support question can be answered; it is not their field
    /// names, their units, or their shape. Without it, at-least-once delivery would translate twice and there
    /// would be nothing in our own history to notice it — the record of what arrived lives in a transport inbox
    /// that is pruned, so the durable answer has to be on the event.
    ///
    /// Arrays rather than <c>List&lt;T&gt;</c> so that <c>Applied.Add(...)</c> is a compile error: an Apply that
    /// mutates the instance Marten handed it is a real bug under projection caching that no test reliably
    /// catches.
    ///
    /// UNBOUNDED, and honestly so — a product with years of notices folds years of Guids on every decision. A
    /// real feed keeps a window, and how late a duplicate may arrive is a domain answer. Left whole here
    /// because a reference that silently truncates teaches the truncation.
    /// </summary>
    public Guid[] Applied { get; init; } = [];

    /// <summary>
    /// The sequence of the newest notice we ACCEPTED. Compared against what was accepted rather than what last
    /// arrived, or a burst of stale notices would ratchet each other through: 3 looks fresh once 2 has been
    /// seen, even though 7 was accepted before either.
    /// </summary>
    public long AcceptedSequence { get; init; }

    public bool HasApplied(Guid noticeId) => Array.IndexOf(Applied, noticeId) >= 0;

    public static TranslateStockNoticeState Apply(StockLevelSet e, TranslateStockNoticeState current) =>
        current with
        {
            Applied = [.. current.Applied, e.NoticeId],
            AcceptedSequence = Math.Max(current.AcceptedSequence, e.Sequence),
